@wheatear-dev

```gdscript
@abstract class_name Class

func run_something() -> void: await do_something()

@abstract func do_something() -> void

@abstract class Class2 extends Class:
	func run_something() -> void: await do_something()
```
And in another script:
```gdscript
@abstract extends Class

func run_something() -> void: await do_something()
```
Putting ```abstract func do_something() -> void``` in the child classes makes no difference.

FYI I just edited my previous comment to say "child" instead of "inherited".

With these two test files, I'm getting segfaults.

```gdscript
@abstract class_name ABC extends RefCounted

@abstract func simulate() -> void

func coroutine() -> void:
	@warning_ignore("redundant_await")
	await 0

func other_method() -> void:
	await simulate()

class ClassAImpl extends ABC:
	func simulate() -> void:
		await coroutine()

func test() -> void:
	var a: ABC = ClassAImpl.new()

	# call simulate from outside
	await a.simulate()

	# call simulate from inside, via other_method
	await a.other_method()
```

```gdscript
@abstract class_name ClassB extends ABC

class ClassBImpl extends ClassB:
	func simulate() -> void:
		await coroutine()

func test() -> void:
	var b: ABC = ClassBImpl.new()

	# call simulate from outside
	await b.simulate()

	# call simulate from inside, via other_method
	await b.other_method()
```

